const V28={placeKey:null,placeResult:null,placeSeq:0,placeBusy:false,plansBusy:false,formPlace:null};
function v28Threshold(term){const point=vResolve(term);if(!point||point.regionOnly||![point.lat,point.lon].every(Number.isFinite))return {point,reason:v20Text('需要具体地点，区级或街道代表位置不用于入口预测。','A specific place is required; district or street centres are not entrance forecasts.')};const name=String(point.name||term).replace(/^深圳市/,'深圳'),plan={origin:name,destination:name,vias:[],mode:'now'},streets=[...new Set(D.risks.filter(r=>r.guide_year===2026&&v12RiskMatches(plan,r).length).map(r=>r.street))];const rows=V28LOCAL.rows.filter(r=>streets.includes(r.street));if(rows.length!==1)return {point,reason:rows.length?v20Text('资料涉及多个街道，尚不能唯一匹配本地阈值。','The sources cover multiple streets; a unique threshold is not matched.'):v20Text('该具体地点没有匹配的街道阈值；不套用其他地点数值。','No street threshold matches this place; another place’s value is not substituted.')};return {point,threshold:v20Copy(rows[0])}}
