function v28PointPanel(r,compact=false){const ready=Number.isFinite(r.percent)&&r.n>=10,street=r.threshold?.street||'',value=ready?r.percent.toFixed(1)+'%':'—';return `<div class="v28point ${ready?'ready':'missing'}"><div class="v28pointhead"><div><small>${esc(v28Where(r.where))}</small><b>${esc(r.point?.name||r.term)}</b><small>${esc(street)}</small></div><div><strong>${value}</strong>${ready?`<span class="v28band">${v28Band(r.percent)}</span>`:''}<small>${v20Text('降雨条件概率 · 模型','Rain-trigger share · Model')}</small></div></div>${ready?`<div class="v28track" role="meter" aria-label="${v20Text('本地降雨条件概率','Local rainfall-trigger share')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${r.percent}"><span style="width:${r.percent}%"></span></div><p class="v28condition">${v20Text('所选3小时内任一小时≥','Any hour in the selected 3-hour window ≥')}${r.threshold.rain1} mm ${v20Text('或累计≥','or the 3-hour total ≥')}${r.threshold.rain3} mm</p><small>${dateText(new Date(r.window.start).toISOString())} — ${dateText(new Date(r.window.end).toISOString())}</small>`:`<p>${esc(r.reason||v20Text('预报未取得','Forecast unavailable'))}</p>`}${!compact&&!/历史情境|Historical scenes/.test(r.reason||'')?`<details><summary>${v20Text('计算、等级与来源','Calculation, bands and sources')}</summary><p>${v20Text('百分比表示预报成员超过所示街道降雨参考条件的比例，不是实际积水、事故或个人危险概率。街道资料不测量此入口，0%不表示通行安全。','The share is the proportion of members exceeding the street rainfall reference, not flooding, accident or personal danger probability. Street evidence does not measure this entrance; 0% does not establish safe access.')}</p>${ready?`<p>P = ${r.count} / ${r.n} × 100% = ${value}；${v20Text('每个成员检查这3个小时中的最大小时雨量及3小时累计，二者任一达标计一次；半小时条件不参与，缺测成员不参与。','Each member tests the largest hourly total and three-hour total, counted once if either threshold is reached. Half-hour conditions and incomplete members are excluded.')}</p><p>${v20Text('预报中位数：最大小时','Ensemble median: largest hourly')}${r.median1.toFixed(1)} mm；${v20Text('3小时累计','three-hour total')} ${r.median3.toFixed(1)} mm。${v20Text('计算从出发所在整点起，并非逐分钟预测。','The window starts at the departure hour, not a minute-resolution forecast.')}</p><p>${v20Text('模型获取时刻：','Model retrieved: ')}${dateText(r.fetched)} · ${r.model} · ${r.n}/${r.totalMembers} ${v20Text('有效成员','valid members')}</p>`:''}${r.threshold?`<p>${v20Text('官方原始条件：','Original reference: ')}<span data-original>${esc(r.threshold.original)}</span></p>`:''}<p>${v20Text('提示档位为Demo规则：低于10%信号较少；10—30%需关注；30—60%较强；60%以上优先调整非必要户外安排。不是官方预警等级，尚未开展本地概率校准。','Demo advisory bands: below 10%, low signal; 10–30%, attention; 30–60%, elevated; 60% or more, prioritise changing non-essential outdoor arrangements. These are not official warnings and are not locally calibrated.')}</p><p><a href="${V28LOCAL.notice}" target="_blank" rel="noopener">${v20Text('2026官方指引与附件','2026 official guidance and attachment')} ↗</a> · <a href="${V18RAIN_SOURCE}" target="_blank" rel="noopener">${v20Text('集合模型定义','Ensemble definitions')} ↗</a></p><p>${v20Text('积水监测尚未接入；不把河流流量、湿度或气压当作道路水深。','Standing-water monitoring is not connected; river discharge, humidity and pressure are not street depth.')}</p></details>`:''}</div>`}
v20Impact=function(p){const a=v28Rank(p);return {...a,reason:a.why}};
v20DecisionPanel=function(){const plans=v11Group();return `<section class="v20decisions v28decisions"><div class="row"><h3>${v20Text('两程影响与安排','Impact and arrangements for both legs')}</h3><small>${v20Text('具体地点 · 具体时段 · 不是事故概率','Specific places and periods · Not accident probability')}</small></div>${plans.map(p=>{const a=v28Rank(p),rr=v28Results(p);return `<article class="v28leg ${a.level}"><div class="row"><h4>${p.leg==='return'?v20Text('返程','Return'):v20Text('去程','Outbound')} · ${esc(p.origin)} → ${esc(p.destination)}</h4><span class="tag ${a.level}">${a.title}</span></div><small>${esc(v28Transport(p.transport))} · ${dateText(p.planned||p.created)}</small><p><b>${v20Text('安排：','Arrangement: ')}</b>${a.action}</p><p class="v28why">${a.why}</p>${p.mode==='history'?`<p>${v20Text('保留当时已公开的公告与隐患，不补算历史天气概率。','Period notices and hazards are retained; historical weather probabilities are not backfilled.')}</p>`:`<div class="v28pointgrid">${rr.map(r=>v28PointPanel(r)).join('')}</div>`}<div class="v28specific">${vRisks(p).map(r=>`<p><b>${esc(r.street)}</b> · <span data-original>${esc(v28Clause(p,r))}</span></p>`).join('')||`<p>${v20Text('这条行程没有匹配的专项易积水条款。','No place-specific flood-prone clause matches this trip.')}</p>`}</div></article>`}).join('')||`<p>${v20Text('查询往返后，分别显示两程的安排、起终点降雨条件概率和具体隐患。','Query a round trip for each leg’s arrangements, location rain-trigger shares and specific hazards.')}</p>`}${plans.some(p=>p.mode==='now')?`<button data-v28="refresh-plans" ${V28.plansBusy?'disabled aria-busy="true"':''}>${v20Text('更新两程地点预报','Update forecasts for both legs')}</button>`:''}<button class="linkbutton" data-v28="explain">${v20Text('风险资料说明','About the risk evidence')}</button></section>`};
const v28RainPanelBase=v18RainPanel;v18RainPanel=function(p){return `<details class="v28generic"><summary>${v20Text('补充：3小时50毫米强降雨预报','Additional: ≥50 mm in 3 hours')}</summary>${v28RainPanelBase(p)}</details>`};
function v28PlaceForecast(){const p={mode:V2.mode,planned:new Date().toISOString()},r=V2.mode==='now'&&V28.placeResult?.term===V5.place?V28.placeResult:v28Live(V5.place,p);return `<section class="v28place"><h3>${v20Text('这个地点的降雨与安排','Rainfall and arrangements for this place')}</h3>${v28PointPanel(r)}${V2.mode==='now'?`<p class="v28why">${v28PlaceAdvice(r)}</p>`:''}${V2.mode==='now'?`<button data-v28="refresh-place" ${V28.placeBusy?'disabled':''}>${v20Text(V28.placeBusy?'正在更新地点预报…':'更新地点预报',V28.placeBusy?'Updating location forecast…':'Update location forecast')}</button>`:''}<button class="linkbutton" data-v28="explain">${v20Text('风险资料说明','About the risk evidence')}</button></section>`}
const v28PlaceBase=v5PlaceDetail;v5PlaceDetail=function(){let h=v28PlaceBase();if(!V5.place)return h;return h.replace('<div class="v10placefacts">','<div class="v10placefacts">'+v28PlaceForecast())};
async function v28LoadPlace(force=false){const term=V5.place,mode=V2.mode,seq=++V28.placeSeq;if(mode!=='now'||!term){V28.placeResult=null;return}const q=v28Threshold(term);if(!q.threshold){V28.placeResult={term,...q};return}V28.placeBusy=true;try{await v18LoadRain(q.point,force);if(seq===V28.placeSeq&&V5.place===term&&V2.mode===mode)V28.placeResult=v28Live(term,{mode:'now',planned:new Date().toISOString()})}finally{if(seq===V28.placeSeq){V28.placeBusy=false;vRender()}}}
function v28Explain(){vDialog(v20Text('风险资料说明','About the risk evidence'),`<p>${v20Text('先看与你的行程对应的停运或封闭，再看本地降雨条件与具体易积水地点。模型比例不能取消官方限制，也不能证明入口安全。','First consider matching suspensions or closures, then local rainfall triggers and flood-prone places. Model shares do not override restrictions or establish entrance safety.')}</p><h3>${v20Text('当前资料覆盖','Current evidence coverage')}</h3><p>${v20Text('已核对罗湖10个街道的2026版降雨阈值；集合预报只计算匹配到具体坐标的地点。实时积涝水位数据未接入，历史情境不使用后来资料。','The 2026 rainfall thresholds for ten Luohu streets are checked. Ensemble calculations require specific coordinates. Live standing-water observations are not connected, and later data are excluded from historical scenes.')}</p><a href="${V28LOCAL.notice}" target="_blank" rel="noopener">${v20Text('官方指引','Official guidance')} ↗</a><details><summary>${v20Text('台风与大风资料','Typhoon and wind guidance')}</summary><p>${v20Text('风速与阵风属于模型参考，当前官方预警状态未自动取得。','Wind and gusts are model references; current official warnings are not automatically retrieved.')}</p>${v26TyphoonGuide()}<a href="${V26SOURCES.warning}" target="_blank" rel="noopener">${v20Text('深圳官方预警','Shenzhen official warnings')} ↗</a></details>`)}
const v28RenderBase=vRender;vRender=function(){const placeInput=document.querySelector('#v5-place-form input'),placeDraft=V2.page==='map'&&V28.formPlace===V5.place&&placeInput?placeInput.value:null;V28.formPlace=V5.place;let loadPlace=false;if(V3.role==='user'&&V2.page==='map'){const key=V2.mode+'|'+V5.place+'|'+Math.floor(Date.now()/3600000);if(key!==V28.placeKey){V28.placeKey=key;V28.placeResult=null;V28.placeBusy=false;V28.placeSeq++;loadPlace=true}}v28RenderBase();if(placeDraft!==null){const input=document.querySelector('#v5-place-form input');if(input)input.value=placeDraft}document.getElementById('v25-common-links')?.remove();const nav=document.querySelector('nav');if(nav&&!document.getElementById('v28-about-link')&&typeof nav.insertAdjacentHTML==='function')nav.insertAdjacentHTML('beforeend',`<button id="v28-about-link" data-v25="about">${icon('shield',16)}<span>${v20Text('关于我们','About us')}</span></button>`);if(loadPlace)Promise.resolve().then(()=>v28LoadPlace())};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v28]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.v28==='explain')return v28Explain();if(b.dataset.v28==='refresh-place')return v28LoadPlace(true);if(b.dataset.v28==='refresh-plans'){if(V20.queryTime)return toast(v20Text('当前是保存的查询；点击重新查询以生成新的地点预报。','This is a saved query; run a new query to generate new location forecasts.'));b.disabled=true;try{await v28LoadPlans(true)}finally{if(b.isConnected)b.disabled=false}}},true);
const v28ExportBase=vExportParts;vExportParts=function(s,c){const parts=v28ExportBase(s,c);if(!s.scope&&s.mode==='now'&&(c.journey||c.weather||c.official)){const lines=(s.plans||[]).flatMap(p=>(p.localRiskSnapshots||[]).map(r=>`${p.leg==='return'?'返程':'去程'} · ${r.where} · ${r.point?.name||r.term}\n${r.n?`超过本地降雨参考条件的模型比例：${r.percent.toFixed(1)}%；${r.count}/${r.n}成员；${r.threshold.street} 1小时≥${r.threshold.rain1}mm 或3小时≥${r.threshold.rain3}mm；半小时条件未计算。\n${dateText(new Date(r.window.start).toISOString())}—${dateText(new Date(r.window.end).toISOString())}；获取${dateText(r.fetched)}`:r.reason}\n来源：${V28LOCAL.source}`));if(lines.length)parts.push({title:v20Text('本地降雨条件概率与依据','Local rainfall triggers and evidence'),text:lines.join('\n\n')+'\n模型成员比例不是实际积水或事故概率，低比例不能抵消停运或封闭。'})}return parts};

function v28Clause(p,r){const hits=v12RiskMatches(p,r).map(m=>m.hit);const chunks=r.risk_description.split(/[。；]/).filter(s=>s.trim());const matched=chunks.filter(s=>hits.some(h=>s.includes(h)));return (matched.length?matched:chunks).join('；')+'。'}
const v28UnpackBase=v20UnpackSnapshot;v20UnpackSnapshot=function(x){const s=v28UnpackBase(x);for(const p of s.plans){if(p.localRiskSnapshots!==undefined){if(!Array.isArray(p.localRiskSnapshots)||p.localRiskSnapshots.length>6)throw Error('本地概率快照无效');for(const r of p.localRiskSnapshots){if(typeof r.term!=='string'||r.term.length>300||typeof r.where!=='string'||r.where.length>100)throw Error('本地地点快照无效');if(r.n){const row=V28LOCAL.rows.find(t=>t.street===r.threshold?.street);if(p.mode!=='now'||!row||row.rain1!==r.threshold.rain1||row.rain3!==r.threshold.rain3||!Number.isInteger(r.n)||r.n<10||r.n>300||!Number.isInteger(r.count)||r.count<0||r.count>r.n||!Number.isFinite(r.percent)||Math.abs(r.percent-r.count/r.n*100)>0.00001||![r.median1,r.median3,r.medianRatio].every(v=>Number.isFinite(v)&&v>=0)||!Number.isFinite(r.window?.start)||!Number.isFinite(r.window?.end)||r.window.end-r.window.start!==10800000||!Number.isFinite(Date.parse(r.fetched))||typeof r.point?.name!=='string'||r.point.name.length>300||![r.point.lat,r.point.lon].every(Number.isFinite)||r.point.lon<113.5||r.point.lon>114.8||r.point.lat<22.2||r.point.lat>23.1)throw Error('本地概率数值或来源无效');r.threshold=v20Copy(row);r.source=V28LOCAL.source;r.sourcePublished=V28LOCAL.published;r.model=V18RAIN_MODEL;}else if(typeof r.reason!=='string'||r.reason.length>1000)throw Error('本地概率状态无效')}}}return s};

function v28PlaceAdvice(r){if(!r.n)return v20Text('此地点尚未取得完整降雨计算结果。下方如有易积水条款，可用于规划避让位置；未匹配资料不代表没有风险。','A complete rainfall calculation is not available for this place. Any flood-prone clauses below can support avoidance planning; unmatched evidence does not establish that risk is absent.');const service=v13Service(V5.place);if(service?.level==='red')return v20Text('此地点有对应停运或封闭记录，请调整涉及该区段的安排；降雨比例不能抵消限制。','Matching suspensions or closures affect this place. Change arrangements for that section; rainfall shares do not override restrictions.');if(r.n&&r.percent>=30)return v20Text('本地降雨触发信号较强，建议延后非必要户外安排，并避开下方列出的低洼位置。','The local rainfall-trigger signal is elevated. Postpone non-essential outdoor plans and avoid the listed low-lying locations.');return v20Text('低预报比例不代表低洼入口没有积水。规划出行时，可把下方列出的易积水位置作为避让点。','A low model share does not establish that a low-lying entrance is dry. Use the flood-prone places listed below as avoidance points when planning travel.')}

function v28Where(s){if(!s)return v20Text('所选地点','Selected place');if(s==='起点'||s==='Origin')return v20Text('起点','Origin');if(s==='终点'||s==='Destination')return v20Text('终点','Destination');return String(s).replace(/^(途经点|Via )/,v20Text('途经点','Via '))}
function v28Transport(s){return ({'公共交通':v20Text('公共交通','Public transport'),'步行':v20Text('步行','Walking'),'驾车':v20Text('驾车','Driving')})[s]||s}

function v28Band(p){return p>=60?v20Text('优先调整','Prioritise changes'):p>=30?v20Text('信号较强','Elevated signal'):p>=10?v20Text('需关注','Attention'):v20Text('信号较少','Low signal')}
